#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=1;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_blurBuf;
float4 amzSample_blurBuf(float2 uv) { return float4(amzt_blurBuf.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_blurBuf(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_amount;
uniform float amzp_width;
uniform float amzp_angle;
uniform float amzp_thickness;
uniform float amzp_phase;
uniform float amzp_invert;
layout(color) uniform half4 amzp_lineColor;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_lightColor;
uniform float amzp_lightAngle;
uniform float amzp_strength;
uniform float amzp_heightSource;
uniform float amzp_maskToLayer;


        float2 l2s( float2 v ) {
            return (float4(v,0.,1.)*amzLayerToScreen()).xy;
        }

        float2x2 rot2d(float a) {
            float c = cos(a);
            float s = sin(a);
            return float2x2( c, -s, s, c );
        }

        const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);

        float2 perpCCW(float2 v) {
            return float2(v.y,-v.x);
        }

        float2 perpCW(float2 v) {
            return float2(-v.y,v.x);
        }

        float4 composite( float4 a, float4 b) {
            return a * (1. - b.a) + b;
        }

        float4 premult( float4 c ) {
            return float4(c.rgb * c.a, c.a);
        }

        void amzRender() {

            float2 st = amzLayerNorm();

            float a = (amzp_angle+180.0) * 0.0174532925;
            float la = (amzp_lightAngle) * 0.0174532925;
            float2 lightVec = float2(1.,0.) * rot2d(la);
            float band = 1. / amzp_amount;

            st -= 0.5;
            st *= rot2d(a);
            st += 0.5;

            st.y += (amzp_phase + 0.055) / 10. + 0.5/layer.y;

            float4 result = float4(0.);

            float pixel = 1./min(layer.x, layer.y);
            float soffs = pixel * 4.0 * max(1.0,amzp_width);
            float bandPixel = pixel/amzp_amount/amzp_width;
            float baseThickness = amzp_thickness / amzp_width * amzp_amount / 20.;

            for( float i=-1.0; i<amzp_width+1.0; i += 1.0 ) {

                float2 uv = st;

                float bandId = floor(uv.y / band) + i;
                float py = mod(uv.y,band);
                uv.y -= py;
                uv.y += band * i;
                py /= band;

                uv.y -= (amzp_phase + 0.055) / 10. + 0.5/layer.y;
                uv -= 0.5;
                uv *= rot2d(-a);
                uv += 0.5;

                py = 1.-((1.-py) + i)/amzp_width;

                float4 texColor = amzTexture(0,l2s(uv));
                float4 texColorL = amzTexture(1,l2s(uv+float2(-soffs,0.)));
                float4 texColorR = amzTexture(1,l2s(uv+float2(soffs,0.)));
                float luminance = int(amzp_heightSource)==0 ? texColor.a : dot(texColor.rgb, luminanceWeighting);
                float lumL = int(amzp_heightSource)==0 ? texColorL.a : dot(texColorL.rgb, luminanceWeighting);
                float lumR = int(amzp_heightSource)==0 ? texColorR.a : dot(texColorR.rgb, luminanceWeighting);
                if( !(amzp_invert>0.5) ) {
                    lumL = 1. - lumL;
                    lumR = 1. - lumR;
                    luminance = 1. - luminance;
                }

                float2 aa = float2(-soffs, lumL*band*amzp_width);
                float2 cc = float2(soffs, lumR*band*amzp_width);
                float2 n = normalize(perpCCW(cc-aa));

                float2 dac = cc-aa;
                float slope = abs(dac.y) / abs(dac.x);

                float th = baseThickness * (1.+slope*0.5);

                float line = smoothstep(luminance-th-bandPixel,luminance-th,py) * smoothstep(luminance+th+bandPixel,luminance+th,py);

                float2 vn = n*0.5 + 0.5;
                float4 lc = saturate(mix(amzp_lineColor,composite(amzp_lineColor,premult(amzp_lightColor)),saturate(dot(n,lightVec))) * saturate(line));

                float p = smoothstep(luminance-0.02,luminance+0.01,py);

                float4 c = texColor * p;
                if(int(amzp_heightSource) == 0) {
                    c = mix(composite(texColor,premult(amzp_color1)), composite(texColor,premult(amzp_color2)), py) * p;
                } else {
                    c = mix(premult(amzp_color1), premult(amzp_color2), py) * p;
                }
                if((amzp_maskToLayer>0.5)) {
                    c *= texColor.a;
                    lc *= texColor.a;
                }
                result = result * (1.-c.a) + c;
                result = result * (1.-lc.a) + lc;
            }


            amzOutput = result;
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

